/**
 * Site search — opens a native <dialog> (Esc, focus trap and inert background
 * come for free), lazily loads search-index.json (generated by .eleventy.js on
 * every build) and matches all query words against title, headings and text.
 * Matching ignores case and Serbian diacritics ("sta" finds "šta").
 */
(function () {
  "use strict";

  const dialog = document.getElementById("search-dialog");
  const openBtns = document.querySelectorAll("[data-search-open]");
  if (!dialog || !openBtns.length || typeof dialog.showModal !== "function") return;

  const form = dialog.querySelector("[data-search-form]");
  const input = dialog.querySelector("[data-search-input]");
  const status = dialog.querySelector("[data-search-status]");
  const list = dialog.querySelector("[data-search-results]");
  const MAX_RESULTS = 12;

  // Internal URLs are emitted relative to each page, so the site root (on the
  // GitHub Pages subpath or locally) is wherever the logo's home link points.
  const homeLink = document.querySelector(".header .logo");
  const siteRoot = new URL(homeLink ? homeLink.getAttribute("href") : "./", window.location.href);
  const toSiteUrl = (rootPath) => new URL(rootPath.replace(/^\//, ""), siteRoot).href;

  const fold = (s) =>
    s.toLowerCase().replace(/đ/g, "d").normalize("NFD").replace(/[̀-ͯ]/g, "");

  const escapeHtml = (s) =>
    s.replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));

  let index = null;
  let loading = null;

  function loadIndex() {
    if (!loading) {
      loading = fetch(toSiteUrl("/search-index.json"))
        .then((r) => {
          if (!r.ok) throw new Error(r.status);
          return r.json();
        })
        .then((pages) => {
          index = pages.map((p) => ({
            ...p,
            fTitle: fold(p.title),
            fHeadings: fold(p.headings.join(" · ")),
            fText: fold(p.text),
          }));
        })
        .catch(() => {
          loading = null;
          status.textContent = "Pretraga trenutno nije dostupna.";
        });
    }
    return loading;
  }

  // Snippet around the first match; fold() keeps string length except for
  // combining marks, so search in the folded text and cut the original.
  function snippet(page, terms) {
    const text = page.text;
    const folded = fold(text);
    let at = -1;
    for (const t of terms) {
      const i = folded.indexOf(t);
      if (i >= 0 && (at < 0 || i < at)) at = i;
    }
    if (at < 0) return escapeHtml(text.slice(0, 160)) + (text.length > 160 ? "…" : "");
    // Snap the window to word boundaries so the snippet never starts mid-word.
    let start = Math.max(0, at - 60);
    if (start > 0) start = text.indexOf(" ", start) + 1 || start;
    let end = Math.min(text.length, at + 140);
    if (end < text.length) end = text.lastIndexOf(" ", end) > at ? text.lastIndexOf(" ", end) : end;
    let html = escapeHtml(text.slice(start, end));
    for (const t of terms) {
      const re = new RegExp(t.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"), "gi");
      // Highlight only when the folded term equals the visible text (no diacritics).
      html = html.replace(re, (m) => (fold(m) === t ? "<mark>" + m + "</mark>" : m));
    }
    return (start > 0 ? "…" : "") + html + (end < text.length ? "…" : "");
  }

  function search(query) {
    const terms = fold(query).split(/\s+/).filter((t) => t.length > 1);
    if (!terms.length) return [];
    return index
      .map((p) => {
        let score = 0;
        for (const t of terms) {
          const inTitle = p.fTitle.includes(t);
          const inHeadings = p.fHeadings.includes(t);
          const inText = p.fText.includes(t);
          if (!inTitle && !inHeadings && !inText) return null;
          score += (inTitle ? 10 : 0) + (inHeadings ? 4 : 0) + (inText ? 1 : 0);
        }
        return { page: p, score, terms };
      })
      .filter(Boolean)
      .sort((a, b) => b.score - a.score);
  }

  function render() {
    const query = input.value.trim();
    list.innerHTML = "";
    if (!index) return;
    if (query.length < 2) {
      status.textContent = "";
      return;
    }
    const hits = search(query);
    status.textContent = hits.length
      ? "Broj rezultata: " + hits.length + (hits.length > MAX_RESULTS ? " (prikazano " + MAX_RESULTS + ")" : "")
      : "Nema rezultata za „" + query + "“.";
    list.innerHTML = hits
      .slice(0, MAX_RESULTS)
      .map(
        (h) =>
          '<li><a class="search-result" href="' + escapeHtml(toSiteUrl(h.page.url)) + '">' +
          '<span class="search-result-title">' + escapeHtml(h.page.title) + "</span>" +
          '<span class="search-result-snippet">' + snippet(h.page, h.terms) + "</span></a></li>"
      )
      .join("");
  }

  openBtns.forEach((btn) =>
    btn.addEventListener("click", () => {
      dialog.showModal();
      input.focus();
      loadIndex().then(render);
    })
  );

  dialog.querySelectorAll("[data-search-close]").forEach((btn) =>
    btn.addEventListener("click", () => dialog.close())
  );

  // Click on the backdrop (outside the inner panel) closes the dialog.
  dialog.addEventListener("click", (e) => {
    if (e.target === dialog) dialog.close();
  });

  let timer;
  input.addEventListener("input", () => {
    clearTimeout(timer);
    timer = setTimeout(() => (index ? render() : loadIndex().then(render)), 120);
  });

  // Enter jumps to the first result instead of submitting the form.
  form.addEventListener("submit", (e) => {
    e.preventDefault();
    const first = list.querySelector("a");
    if (first) window.location.href = first.href;
  });
})();
